 namespace Pterodactyl\Services\Dezerx\Importer; use Pterodactyl\Models\Dezerx\ImportHost; use Pterodactyl\Models\Dezerx\ImportCredential; class Credentials { private bool $resolvedAddressLoaded = false; private ?string $resolvedAddressValue = null; public function __construct( public readonly string $host, public readonly int $port, public readonly string $mode, public readonly string $username, public readonly string $auth, public readonly string $secret, public readonly string $passphrase, public readonly string $path, public readonly ?int $hostProfile = null, public readonly ?int $credentialProfile = null, ) { } public static function make( ?ImportHost $host, ?ImportCredential $credential, array $input, string $path = '', ): self { $mode = in_array($input['mode'] ?? '', ImportHost::MODES, true) ? (string) $input['mode'] : null; $auth = in_array($input['auth'] ?? '', ImportCredential::AUTH, true) ? (string) $input['auth'] : null; $resolvedMode = $host?->mode ?? $mode ?? 'sftp'; $normalized = self::normalizeHost((string) ($host->host ?? $input['host'] ?? '')); if ($host !== null) { $port = $host->port; } else { $inputPort = (int) ($input['port'] ?? 0); $port = $normalized['port'] ?? ($inputPort > 0 && $inputPort <= 65535 ? $inputPort : ($resolvedMode === 'ftp' ? 21 : 22)); } return new self( host: $normalized['host'], port: $port, mode: $resolvedMode, username: trim((string) ($credential->username ?? $input['username'] ?? '')), auth: $credential->auth ?? $auth ?? 'password', secret: (string) ($credential->secret ?? $input['secret'] ?? ''), passphrase: (string) ($credential->passphrase ?? $input['passphrase'] ?? ''), path: $path !== '' ? $path : (string) ($host->path ?? $input['path'] ?? ''), hostProfile: $host === null ? null : (int) $host->id, credentialProfile: $credential === null ? null : (int) $credential->id, ); } public static function resolve(?int $hostProfile, ?int $credentialProfile, array $custom, string $path): ?self { $host = $hostProfile === null ? n